const horizons=[
 {year:2028,kicker:'NEAR TERM · DELIVERY',head:'Projects already in the program',copy:'The near-term program includes SMART’s extension toward Healdsburg, Valley Rail work and improvements to existing routes. The 2024 plan also places the Las Vegas high-speed connection in this horizon.',status:'Funding status in the 2024 plan: funded or committed. Check individual projects for current schedules and commitments.',region:'state'},
 {year:2034,kicker:'MID TERM · IMPLEMENTATION',head:'Connections to initial high-speed rail',copy:'The mid-term plan introduces hourly Merced–Bakersfield high-speed service. Connections at Merced, the Portal in San Francisco and work at LA Union Station are important parts of the wider program.',status:'In the 2024 plan, projects are funded or have an identified path to funding. That does not mean every funding gap is closed.',region:'valley'},
 {year:2050,kicker:'LONG TERM · PLANNING',head:'Extensions and additional capacity',copy:'The long-term network includes the full Phase 1 high-speed route, a second rail crossing of the Bay and additional regional lines. Much of this work still requires planning, approvals and financing.',status:'Most long-term funding had not been identified when the plan was published.',region:'state'}
];
const actions=[
 {n:'01',title:'Which timetable is the project designed for?',text:'An extra track has value because of the service it allows. Ask the sponsor to show the proposed timetable, expected journey times and connections, and the reliability standard the design is meant to meet.',roles:['state','regional'],pages:[15,16,20]},
 {n:'02',title:'Who will pay to run the service?',text:'Operating costs continue after construction ends. A funding proposal should explain who will provide the trains and crews, maintain the equipment and infrastructure, and cover any gap between fares and costs.',roles:['state','regional'],pages:[17,18,51]},
 {n:'03',title:'Is there agreement with the railroad?',text:'Much of the network uses tracks owned by freight railroads. More passenger trains require an agreed place in the timetable, along with arrangements for dispatching and maintenance. Those agreements can determine whether a proposed service is workable.',roles:['state','regional'],pages:[19,20,51,52]},
 {n:'04',title:'Which connections need a joint plan?',text:'At Merced, for example, separate agencies have to agree on platforms, schedules and transfers. Similar questions arise at Rancho Cucamonga and Union Station. A useful project plan identifies who is responsible for each shared decision.',roles:['state','regional','local'],pages:[21,24,25,52]},
 {n:'05',title:'How will the line remain usable?',text:'Emergency repairs and long-term adaptation serve different purposes. Ask how the project addresses the risks on its route, how alternatives affect neighboring communities, and how service will be maintained during the work.',roles:['state','regional','local'],pages:[53,55,58,59]},
 {n:'06',title:'How will people reach the station?',text:'The journey includes the trip to and from the platform. Local decisions about housing, bus connections, safe walking routes and accessibility affect whether people can use the rail service. Plans should also consider displacement around station areas.',roles:['local','regional'],pages:[15,16,23]}
];
function renderDelivery(){const roleLabel={all:'all public agencies',state:'state officials',regional:'regional boards',local:'cities and counties'}[state.role],count=actions.filter(a=>state.role==='all'||a.roles.includes(state.role)).length;$('role-summary').textContent=count+' questions relevant to '+roleLabel+'.'; $('horizon-cards').innerHTML=horizons.map(h=>`<article class="horizon-card"><div class="card-kicker">${h.kicker}</div><div class="h-year">${h.year}</div><h3>${h.head}</h3><p>${h.copy}</p><div class="h-status">${h.status}</div><button class="text-btn" data-horizon-map="${h.year}" data-zoom-region="${h.region}">Explore this horizon ${icon('arrow')}</button></article>`).join('');$('action-cards').innerHTML=actions.map(a=>`<article class="action-card ${state.role!=='all'&&!a.roles.includes(state.role)?'dim':''}" ${state.role!=='all'&&!a.roles.includes(state.role)?'hidden':''}><div class="action-num">${a.n}</div><h3>${a.title}</h3><p>${a.text}</p><div class="action-roles">${a.roles.map(r=>`<span>${r==='local'?'Cities / counties':r==='regional'?'Regional boards':'State'}</span>`).join('')}</div>${source(a.pages[0],`Plan pp. ${a.pages.join(', ')}`)}</article>`).join('');$('unlock-grid').innerHTML=PROJECTS.filter(p=>p.primary).map(p=>`<button class="unlock-card" data-project="${p.id}"><span class="unlock-number">${PROJECTS.indexOf(p)+1}</span><span><h3>${esc(p.name)}</h3><p>${p.category} · ${p.year} horizon</p></span>${icon('arrow')}</button>`).join('') }
const tableState={q:'',horizon:'all',category:'all',page:0,sort:'name',direction:1,expanded:null};
function filteredCapital(){let q=tableState.q.toLowerCase().trim();return CAP.filter(c=>(tableState.horizon==='all'||c.horizon===tableState.horizon)&&(tableState.category==='all'||c.category===tableState.category)&&(!q||[c.name,c.description,c.agency,c.category].join(' ').toLowerCase().includes(q))).sort((a,b)=>{let d;if(tableState.sort==='cost')d=a.cost-b.cost;else if(tableState.sort==='horizon')d=['Near Term','Mid Term','Long Term'].indexOf(a.horizon)-['Near Term','Mid Term','Long Term'].indexOf(b.horizon);else d=a.name.localeCompare(b.name);return d*tableState.direction})}
function renderCapital(){const all=filteredCapital();let pages=Math.max(1,Math.ceil(all.length/15));tableState.page=Math.min(tableState.page,pages-1);let rows=all.slice(tableState.page*15,(tableState.page+1)*15);$('capital-body').innerHTML=rows.length?rows.map(c=>{const project=PROJECTS.find(p=>p.capitalId===c.id);return `<tr><td><button data-capital-expand="${c.id}" aria-expanded="${tableState.expanded===c.id}">${esc(c.name)}</button></td><td><span class="phase-tag">${esc(c.horizon.replace(' Term',''))}</span></td><td>${esc(c.agency)}</td><td class="money">${money(c.cost,true)}</td><td><a class="source-link" href="${APPENDIX}#page=${c.pdfPage}" target="_blank" rel="noopener">PDF p. ${c.pdfPage} ↗</a></td></tr>${tableState.expanded===c.id?`<tr class="cap-expanded"><td colspan="5"><p>${esc(c.description||'No description is given in this fleet table; see the original source entry.')}</p><small>${esc(c.category)} · Original appendix wording · 2024 planning estimate, not current funding status</small>${project?`<button class="text-btn" data-project="${project.id}">Explore the network dependency ${icon('arrow')}</button>`:''}</td></tr>`:''}`}).join(''):'<tr><td colspan="5">No matching entries. Try a city, agency or broader project term.</td></tr>';$('capital-count').textContent=all.length?`${tableState.page*15+1}–${Math.min((tableState.page+1)*15,all.length)} of ${all.length} entries`:'0 matching entries';$('capital-prev').disabled=tableState.page===0;$('capital-next').disabled=tableState.page>=pages-1;document.querySelectorAll('[data-sort]').forEach(b=>b.parentElement.setAttribute('aria-sort',b.dataset.sort===tableState.sort?(tableState.direction===1?'ascending':'descending'):'none'))}
function openRegister(id){let c=CAP.find(x=>x.id===id);if(!c)return;tableState.q=c.name;tableState.horizon='all';tableState.category='all';tableState.page=0;tableState.expanded=id;$('capital-search').value=c.name;$('capital-horizon').value='all';$('capital-category').value='all';renderCapital();setView('delivery');requestAnimationFrame(()=>{$('capital-register').scrollIntoView({behavior:'smooth',block:'start'});document.querySelector('[data-capital-expand="'+id+'"]')?.focus({preventScroll:true})})}
const searchAliases={slo:'san luis obispo',la:'los angeles',sf:'san francisco',sj:'san jose',sd:'san diego',sac:'sacramento',hsr:'high speed',ie:'inland empire',oc:'orange county',mitc:'merced intermodal track connection'};
function normalizedSearch(s){return String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function search(q){
 const raw=normalizedSearch(q),value=searchAliases[raw]||raw;
 if(raw.length<2){closeSearch();return}
 const tokens=value.split(/\s+/),found=[];
 function add(type,id,name,sub,extra,iconName){
  const title=normalizedSearch(name),hay=normalizedSearch(name+' '+extra);
  if(!tokens.every(t=>hay.includes(t)))return;
  const priority={city:4,route:3,project:2,capital:1}[type];
  const score=(title===value?100:title.startsWith(value)?70:title.includes(value)?50:20)+priority;
  found.push({type,id,name,sub,icon:iconName,score});
 }
 N.cities.forEach(c=>add('city',c.id,c.name,c.region,c.region+' '+c.connections,'pin'));
 N.routes.forEach(r=>add('route',r.id,r.name,r.baseline?'Amtrak · 2024 inventory':kindNames[r.kind],r.group+' '+r.nodes.map(id=>cities[id].name).join(' '),'train'));
 PROJECTS.forEach(p=>add('project',p.id,p.name,'Implementation project',p.unlock+' '+p.capitalName+' '+p.category+' '+p.owners,'briefcase'));
 CAP.forEach(c=>add('capital',c.id,c.name,'Capital register · '+c.horizon,c.description+' '+c.agency,'file'));
 found.sort((a,b)=>b.score-a.score||a.name.localeCompare(b.name));
 const shown=found.slice(0,10),holder=$('search-results');
 holder.innerHTML=shown.length?shown.map(f=>`<button data-search-type="${f.type}" data-search-id="${f.id}"><span class="result-type">${icon(f.icon)}</span><span><b>${esc(f.name)}</b><small>${esc(f.sub)}</small></span></button>`).join('')+`<div class="search-help" role="status">${found.length} ${found.length===1?'result':'results'}. ${found.length>10?'Showing the first 10 matches. Try a more specific name.':'Press Enter to open the first result.'}</div>`:`<p role="status">No match for “${esc(q)}”. Try a place, train route or project name, such as SLO, Coast Starlight or King City.</p>`;
 holder.hidden=false;$('global-search').setAttribute('aria-expanded','true');
}
// File exports are built locally: no web requests, analytics, tiles or API keys.

function saveBlob(content,name,type){const blob=content instanceof Blob?content:new Blob([content],{type});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),15000)}
function csv(rows){if(!rows.length)return '';let keys=Object.keys(rows[0]);let cell=x=>'"'+String(x??'').replace(/"/g,'""')+'"';return '\uFEFF'+[keys.map(cell).join(','),...rows.map(r=>keys.map(k=>cell(r[k])).join(','))].join('\r\n')}
function serviceRows(id){return N.routes.filter(r=>!r.baseline&&(!id||r.id===id)).flatMap(r=>['2028','2034','2050'].map(y=>({corridor_id:r.id,corridor:r.name,service_type:r.kind,horizon:y,active:r.phases[y].active,headway_minutes:r.phases[y].headway??'',frequency:r.phases[y].label,bound:r.phases[y].bound||'',detail:r.phases[y].detail,source_page:r.source.page,source:r.source.url,geometry:r.geometryLabel,notes:r.notes,source_discrepancy:r.conflict||''})))}
function downloadCapital(){saveBlob(csv(CAP.map(c=>({...c,source:APPENDIX+'#page='+c.pdfPage}))),'California-Rail-Capital-Register.csv','text/csv;charset=utf-8');toast('Preparing the full 180-entry capital register.')}
function baselineRows(id){return N.routes.filter(r=>r.baseline&&(!id||r.id===id)).map(r=>({route_id:r.id,route:r.name,service_type:r.kind,basis:'Existing service in the 2024 plan inventory — not a horizon target',inventory_year:r.inventory.year,frequency:r.inventory.frequency,full_route:r.inventory.fullRoute,detail:r.inventory.detail,source_pdf_page:r.source.pdfPage,source:r.source.url,geometry:r.geometryLabel,notes:r.notes}))}
function downloadBaseline(id){saveBlob(csv(baselineRows(id)),id?'California-Rail-'+id+'.csv':'California-Rail-Amtrak-Baseline.csv','text/csv;charset=utf-8');toast('Preparing the existing-service inventory, separate from future goals.')}
function downloadServices(id){if(id&&routes[id]?.baseline){downloadBaseline(id);return}saveBlob(csv(serviceRows(id)),id?'California-Rail-'+id+'.csv':'California-Rail-Service-Goals.csv','text/csv;charset=utf-8');toast('Preparing source-linked service goals as CSV.')}
function downloadBrief(){if(D.briefing){let b=atob(D.briefing),a=new Uint8Array(b.length);for(let i=0;i<b.length;i++)a[i]=b.charCodeAt(i);saveBlob(new Blob([a],{type:'application/pdf'}),'California-Rail-Electeds-Briefing.pdf');toast('Preparing the print-ready elected-official briefing.')}else{toast('The companion PDF is available with the atlas files.');}}
function downloadGeo(){saveBlob(JSON.stringify(D.geojson,null,2),'California-Rail-Vision-Corridors.geojson','application/geo+json');toast('Preparing generalized corridor GeoJSON with source metadata.')}
function exportMap(){const svg=$('rail-map').cloneNode(true);svg.removeAttribute('tabindex');svg.removeAttribute('id');svg.setAttribute('xmlns','http://www.w3.org/2000/svg');svg.setAttribute('width',state.w);svg.setAttribute('height',state.h);let bg=document.createElementNS('http://www.w3.org/2000/svg','rect');bg.setAttribute('width','100%');bg.setAttribute('height','100%');bg.setAttribute('fill','#e4eef0');svg.insertBefore(bg,svg.firstChild);svg.querySelector('#route-hit-layer')?.remove();let ff=(document.querySelector('style')?.textContent.match(/@font-face\{[^}]+\}/g)||[]).join('');if(ff){let style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent=ff;svg.querySelector('defs').append(style)}svg.querySelectorAll('[data-city],[data-project],[data-route]').forEach(e=>e.removeAttribute('style'));let ns='http://www.w3.org/2000/svg',footer=document.createElementNS(ns,'g'),y=state.h-99,w=Math.min(530,state.w-24);footer.innerHTML=`<rect x="12" y="${y}" width="${w}" height="88" rx="5" fill="#fbfcf5" stroke="#d3dfcc"/><text x="25" y="${y+19}" font-size="13" fill="#214639" font-family="Arial,sans-serif">California, connected · ${state.year} planning goals</text><text x="25" y="${y+37}" font-size="8.2" fill="#627f50" font-family="Arial,sans-serif">${state.color==='frequency'?'≤15′ green · 30′ blue · 60′ purple · 120′ gold · 240′ clay':'HSR red · intercity blue · regional green · integrated bus gray'}</text><text x="25" y="${y+52}" font-size="7.6" fill="#627f50" font-family="Arial,sans-serif">Thicker targets = more frequent. Dotted gray = bus. Dashed = generalized.</text><text x="25" y="${y+66}" font-size="7.6" fill="#627f50" font-family="Arial,sans-serif">Fine gray Amtrak = 2024 inventory. Not a timetable or funding award.</text><text x="25" y="${y+79}" font-size="7" fill="#879676" font-family="Arial,sans-serif">Caltrans rail GIS · Natural Earth · Terrain Tiles · EPSG:3310 · independent interpretation</text>`;svg.append(footer);saveBlob('<?xml version="1.0" encoding="UTF-8"?>\n'+new XMLSerializer().serializeToString(svg),`California-Rail-${state.year}-${state.color}-map.svg`,'image/svg+xml');toast('Preparing the current geographic map as SVG.')}
// Event delegation keeps the app self-contained and all dynamic controls functional.
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;
 if(d.view)setView(d.view);
 else if(d.year)setYear(d.year);
 else if(d.color)setColor(d.color);
 else if(d.region)fitRegion(d.region);
 else if(d.route)selectRoute(d.route);
 else if(d.project)selectProject(d.project);
 else if(d.city)selectCity(d.city);
 else if(d.back!==undefined)resetSelection();
 else if(d.startTour!==undefined)startTour();
 else if(d.showProjects!==undefined){state.layers.projects=true;$('layer-projects').checked=true;scheduleRender();toast('Delivery priorities are now on the map. Click a numbered marker.')}
 else if(d.exitTour!==undefined){state.tour=null;resetSelection()}
 else if(d.tourPrev!==undefined){if(state.tour>0){state.tour--;runTourStep()}}
 else if(d.tourNext!==undefined){if(state.tour<5){state.tour++;runTourStep()}else{state.tour=null;state.selected=null;setView('delivery')}}
 else if(d.routeCsv)downloadServices(d.routeCsv);
 else if(d.openRegister)openRegister(d.openRegister);
 else if(d.horizonMap){setYear(d.horizonMap);state.selected=null;setView('explore');fitRegion(d.zoomRegion);renderInspector()}
 else if(d.role){state.role=d.role;document.querySelectorAll('[data-role]').forEach(x=>{x.classList.toggle('active',x.dataset.role===d.role);x.setAttribute('aria-pressed',String(x.dataset.role===d.role))});renderDelivery()}
 else if(d.capitalExpand){tableState.expanded=tableState.expanded===d.capitalExpand?null:d.capitalExpand;renderCapital();updateURL()}
 else if(d.sort){if(tableState.sort===d.sort)tableState.direction*=-1;else{tableState.sort=d.sort;tableState.direction=d.sort==='cost'?-1:1}tableState.page=0;renderCapital()}
 else if(d.searchId){let type=d.searchType,id=d.searchId;closeSearch();$('global-search').value='';if(type==='city')selectCity(id);if(type==='route')selectRoute(id);if(type==='project')selectProject(id);if(type==='capital')openRegister(id)}
});
