$('zoom-in').onclick=()=>zoomAt(1.38);$('zoom-out').onclick=()=>zoomAt(1/1.38);$('reset-map').onclick=()=>fitRegion('state',true);$('layers-btn').onclick=()=>{let open=$('layers-menu').hidden;$('layers-menu').hidden=!open;$('layers-btn').setAttribute('aria-expanded',String(open));$('layers-btn').classList.toggle('active',open)};$('close-layers').onclick=closeLayers;$('export-map').onclick=exportMap;$('fullscreen-btn').onclick=()=>{state.expanded=!state.expanded;document.body.classList.toggle('map-expanded',state.expanded);$('fullscreen-btn').setAttribute('aria-label',state.expanded?'Restore inspector':'Expand map');requestAnimationFrame(resizeMap)};
