$('global-search').addEventListener('input',e=>search(e.target.value));$('global-search').addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('search-results').hidden){e.stopPropagation();closeSearch();}if(e.key==='Enter'&&!$('search-results').hidden){e.preventDefault();$('search-results').querySelector('button')?.click();}if(e.key==='ArrowDown'){e.preventDefault();$('search-results').querySelector('button')?.focus()}});
$('search-results').addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp'].includes(e.key))return;e.preventDefault();let buttons=[...$('search-results').querySelectorAll('button')],i=buttons.indexOf(document.activeElement);buttons[(i+(e.key==='ArrowDown'?1:buttons.length-1))%buttons.length]?.focus()});
