$('capital-search').oninput=e=>{tableState.q=e.target.value;tableState.page=0;renderCapital()};$('capital-horizon').onchange=e=>{tableState.horizon=e.target.value;tableState.page=0;renderCapital()};$('capital-category').onchange=e=>{tableState.category=e.target.value;tableState.page=0;renderCapital()};$('capital-prev').onclick=()=>{tableState.page--;renderCapital()};$('capital-next').onclick=()=>{tableState.page++;renderCapital()};
['briefing-btn','briefing-bottom','download-brief-2'].forEach(id=>$(id).onclick=downloadBrief);['download-capital','download-capital-2'].forEach(id=>$(id).onclick=downloadCapital);$('download-services').onclick=()=>downloadServices();$('download-baseline').onclick=()=>downloadBaseline();$('download-geodata').onclick=downloadGeo;$('show-project-map').onclick=()=>{setView('explore');state.layers.projects=true;$('layer-projects').checked=true;state.selected=null;state.tour=null;fitRegion('state');renderInspector();scheduleRender();toast('Click a numbered delivery priority to see what it unlocks.')};$('inspect-discrepancy').onclick=()=>{setYear('2050');selectRoute('sb-la')};
// Map pointer navigation; city/corridor index offers a parallel keyboard-accessible interface.
const map=$('rail-map'),stage=$('map-stage');map.addEventListener('wheel',e=>{e.preventDefault();let r=map.getBoundingClientRect();zoomAt(Math.exp(-e.deltaY*.0015),e.clientX-r.left,e.clientY-r.top);$('map-tooltip').hidden=true},{passive:false});
map.addEventListener('pointerdown',e=>{if(e.button!==0)return;let r=map.getBoundingClientRect(),target=e.target.closest('[data-route],[data-city],[data-project]');pan={id:e.pointerId,px:e.clientX,py:e.clientY,x:state.x,y:state.y,moved:false,target:target?{...target.dataset}:null};map.setPointerCapture(e.pointerId);stage.classList.add('dragging');$('map-tooltip').hidden=true});
map.addEventListener('pointermove',e=>{if(pan&&pan.id===e.pointerId){let dx=e.clientX-pan.px,dy=e.clientY-pan.py;if(Math.hypot(dx,dy)>4)pan.moved=true;if(pan.moved){state.x=pan.x+dx;state.y=pan.y+dy;state.region='custom';document.querySelectorAll('[data-region]').forEach(e=>e.classList.remove('active'));scheduleRender()}return}let el=e.target.closest('[data-route],[data-city],[data-project]');if(!el){$('map-tooltip').hidden=true;return}let content;if(el.dataset.route){let r=routes[el.dataset.route],ph=activePhase(r);content=`<b>${esc(r.name)}</b>${esc(ph.label)} · ${r.baseline?'2024 inventory':state.year+' goal'}<small>${r.baseline?'Existing Amtrak · not a horizon target':r.geometry==='rail'?'Mapped corridor':'Conceptual / generalized connection'} · click to inspect</small>`}else if(el.dataset.city){let c=cities[el.dataset.city];content=`<b>${esc(c.name)}</b>Explore network connections<small>Selected city / hub</small>`}else{let p=projects[el.dataset.project];content=`<b>${esc(p.name)}</b>${p.year} horizon · ${money(p.cost)}<small>2024 planning entry, not current funding</small>`}let rect=stage.getBoundingClientRect();$('map-tooltip').innerHTML=content;$('map-tooltip').hidden=false;let w=$('map-tooltip').offsetWidth,h=$('map-tooltip').offsetHeight;$('map-tooltip').style.left=Math.min(state.w-w-12,Math.max(12,e.clientX-rect.left+14))+'px';$('map-tooltip').style.top=Math.min(state.h-h-10,Math.max(58,e.clientY-rect.top-18-h))+'px'});
function endPan(e){if(!pan||pan.id!==e.pointerId)return;let p=pan;pan=null;stage.classList.remove('dragging');try{map.releasePointerCapture(e.pointerId)}catch(err){}if(!p.moved&&p.target){if(p.target.route)selectRoute(p.target.route,false);if(p.target.city)selectCity(p.target.city,false);if(p.target.project)selectProject(p.target.project,false)}else if(!p.moved&&state.selected){resetSelection()}}
map.addEventListener('pointerup',endPan);map.addEventListener('pointercancel',()=>{pan=null;stage.classList.remove('dragging')});map.addEventListener('pointerleave',()=>$('map-tooltip').hidden=true);
map.addEventListener('keydown',e=>{let moves={ArrowLeft:[60,0],ArrowRight:[-60,0],ArrowUp:[0,60],ArrowDown:[0,-60]};if(moves[e.key]){e.preventDefault();state.x+=moves[e.key][0];state.y+=moves[e.key][1];state.region='custom';scheduleRender()}if(e.key==='Home'){e.preventDefault();fitRegion('state',true)}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('search-results').hidden){closeSearch();$('global-search').focus();return}if(!$('layers-menu').hidden){closeLayers();$('layers-btn').focus();return}if(innerWidth<=760&&$('sidebar').classList.contains('open')){setMobileInspector(false,true);return}if(state.selected||state.tour!==null)resetSelection();return}if(/INPUT|SELECT|TEXTAREA/.test(e.target.tagName))return;if(e.key==='/'){e.preventDefault();setView('explore');openMobile();$('global-search').focus()}if(state.view==='explore'&&(e.key==='+'||e.key==='=')){e.preventDefault();zoomAt(1.35)}if(state.view==='explore'&&e.key==='-'){e.preventDefault();zoomAt(1/1.35)}});
initBase();renderLegend();renderInspector();renderDelivery();renderCapital();new ResizeObserver(()=>{if(state.view==='explore')resizeMap()}).observe(stage);
try{
 const [requestedView,q]=location.hash.slice(1).split('?'),p=new URLSearchParams(q||''),view=['explore','delivery','sources'].includes(requestedView)?requestedView:'explore';
 if(['2028','2034','2050'].includes(p.get('year')))setYear(p.get('year'));
 if(['frequency','service'].includes(p.get('color')))setColor(p.get('color'));
 setView(view);
 if(view==='explore'){
  const region=p.get('region');if(regionBounds[region])fitRegion(region);
  const focus=!regionBounds[region];
  let id=p.get('route');if(routes[id])selectRoute(id,focus);
  id=p.get('project');if(projects[id])selectProject(id,focus);
  id=p.get('city');if(cities[id])selectCity(id,focus);
 }else if(view==='delivery'&&CAP.some(c=>c.id===p.get('capital')))openRegister(p.get('capital'));
}catch(e){}
